(* Lesson 07 -- FOR Loops & Arrays: Scanning an I/O Bank *)

VAR
    Data        : ARRAY[0..7] OF INT;  (* 8-channel input bank, indices 0..7 *)
    i           : INT;                 (* loop index                         *)
    Total       : DINT;                (* output: running sum                *)
    Alarm_Count : DINT;                (* output: count of channels > 100    *)
END_VAR

(* ----- YOUR LOGIC : write your answer between these two lines ----- *)
Total := 0;
Alarm_Count := 0;
FOR i := 0 TO 7 DO
    Total := Total + Data[i];
    IF Data[i] > 100 THEN
        Alarm_Count := Alarm_Count + 1;
    END_IF;
END_FOR;
(* ------------------------------------------------------------------ *)
